// Saat 08:00'den önceyse ya da bugünün raporu zaten gittiyse dur
const s = $getWorkflowStaticData('global');
const now = $now.setZone('Europe/Istanbul');
const today = now.toFormat('yyyy-MM-dd');
if (now.hour < 8 || s.lastSentDate === today) return [];
return [{ json: { today } }];

// Dünün Meta reklam özetini ve reklam seti uyarılarını hazırlar
const TZ = 'Europe/Istanbul';
const MSG_STARTED = 'onsite_conversion.messaging_conversation_started_7d'; // mesaj başlatan sohbetler
const MSG_NEW = 'onsite_conversion.messaging_first_reply';                // ilk kez yazan kişiler

// Eşikler Ayarlar node'undan geliyor
const cfg = $('Ayarlar').first().json;
const FREQ_LIMIT = Number(cfg.frequencyLimit);          // sıklık bunu geçerse set izlemeye alınır
const COST_UP = Number(cfg.costIncreasePct);            // mesaj başı maliyet kendi ortalamasını bu yüzde kadar aşarsa uyarı
const MIN_SPEND = Number(cfg.minSpend);                 // dün bundan az harcayan sete maliyet uyarısı verilmez
const MIN_BASE_CONV = Number(cfg.minBaseConversations); // önceki günlerde bundan az mesaj varsa ortalama güvenilmez
const FREQ_LABEL = { last_7d: '7 gün', last_14d: '14 gün', last_30d: '30 gün', last_90d: '90 gün', maximum: 'tüm zamanlar' }[cfg.frequencyWindow] || cfg.frequencyWindow;
const MAX_SET_LINES = 15;

const accountRows = $('Meta - Hesap (7 gün)').first().json.data || [];
const adsetRows = $('Meta - Reklam Setleri (7 gün)').first().json.data || [];
const freqRows = $('Meta - Reklam Setleri (sıklık)').first().json.data || [];

const yesterday = $now.setZone(TZ).minus({ days: 1 });
const yStr = yesterday.toFormat('yyyy-MM-dd');
const dateLabel = yesterday.setLocale('tr').toFormat('d MMMM yyyy, cccc');

const num = v => Number(v || 0);
const act = (row, type) => {
  const a = (row.actions || []).find(x => x.action_type === type);
  return a ? Number(a.value) : 0;
};
const summarize = row => {
  const spend = num(row.spend);
  const conversations = act(row, MSG_STARTED);
  return {
    spend,
    reach: num(row.reach),
    impressions: num(row.impressions),
    frequency: num(row.frequency),
    cpm: num(row.cpm),
    conversations,
    newContacts: act(row, MSG_NEW),
    costPerConversation: conversations > 0 ? spend / conversations : null,
  };
};

const currency = (accountRows[0] && accountRows[0].account_currency) || 'TRY';
const money = v => v == null ? '–' : new Intl.NumberFormat('tr-TR', { style: 'currency', currency, maximumFractionDigits: 2 }).format(v);
const int = v => new Intl.NumberFormat('tr-TR').format(Math.round(v));
const dec = v => new Intl.NumberFormat('tr-TR', { maximumFractionDigits: 2 }).format(v);
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const header = `📊 <b>${esc(cfg.businessName)} – Meta Reklam Raporu</b>\n📅 ${dateLabel}`;

const yRow = accountRows.find(r => r.date_start === yStr);
if (!yRow) {
  return [{ json: { hasData: false, text: `${header}\n\n⚠️ Dün hiç reklam harcaması görünmüyor. Reklamlar bilerek durdurulmadıysa ödeme yöntemi ve hesap durumu kontrol edilmeli.`, stats: null } }];
}

const y = summarize(yRow);
const prev = accountRows.filter(r => r.date_start !== yStr).map(summarize);
const prevSpend = prev.reduce((s, r) => s + r.spend, 0);
const prevConv = prev.reduce((s, r) => s + r.conversations, 0);
const base = prev.length ? {
  days: prev.length,
  spend: prevSpend / prev.length,
  conversations: prevConv / prev.length,
  reach: prev.reduce((s, r) => s + r.reach, 0) / prev.length,
  costPerConversation: prevConv > 0 ? prevSpend / prevConv : null,
} : null;

// Önceki günlerin ortalamasına göre değişim (maliyette düşüş = iyi)
const trend = (cur, ref, lowerIsBetter = false) => {
  if (cur == null || ref == null || ref === 0) return '';
  const pct = ((cur - ref) / ref) * 100;
  if (Math.abs(pct) < 5) return ' ➖';
  const good = lowerIsBetter ? pct < 0 : pct > 0;
  return ` ${good ? '🟢' : '🔴'} ${pct > 0 ? '▲' : '▼'}%${Math.abs(Math.round(pct))}`;
};

// --- Reklam setleri: her set dünü kendi önceki günleriyle karşılaştırılır ---
const freqById = {};
for (const r of freqRows) freqById[r.adset_id] = num(r.frequency);

const groups = {};
for (const r of adsetRows) {
  if (!groups[r.adset_id]) groups[r.adset_id] = { id: r.adset_id, name: r.adset_name, campaign: r.campaign_name, rows: [] };
  groups[r.adset_id].rows.push(r);
}
const multiCampaign = new Set(Object.values(groups).map(g => g.campaign)).size > 1;

const sets = [];
for (const g of Object.values(groups)) {
  const yr = g.rows.find(r => r.date_start === yStr);
  if (!yr) continue;
  const d = summarize(yr);
  if (d.spend <= 0) continue;

  const p = g.rows.filter(r => r.date_start !== yStr).map(summarize);
  const pSpend = p.reduce((s, r) => s + r.spend, 0);
  const pConv = p.reduce((s, r) => s + r.conversations, 0);
  const baseCpc = pConv > 0 ? pSpend / pConv : null;
  const costPct = d.costPerConversation != null && baseCpc ? ((d.costPerConversation - baseCpc) / baseCpc) * 100 : null;
  const comparable = baseCpc != null && pConv >= MIN_BASE_CONV && d.spend >= MIN_SPEND;
  const freq = freqById[g.id] != null ? freqById[g.id] : null;

  const alerts = [];
  const notes = [];
  if (d.conversations === 0 && d.spend >= MIN_SPEND && (baseCpc == null || d.spend >= 2 * baseCpc)) {
    alerts.push(baseCpc
      ? `hiç mesaj gelmedi; bu harcama normalde ~${int(d.spend / baseCpc)} mesaj getiriyordu`
      : 'harcama var ama hiç mesaj gelmedi');
  } else if (comparable && costPct != null && costPct >= COST_UP) {
    alerts.push(`kendi ortalaması ${money(baseCpc)}, dün %${Math.round(costPct)} daha pahalı`);
  }
  if (freq != null && freq > FREQ_LIMIT) {
    // Sıklık tek başına karar değil: maliyet de bozuluyorsa uyarı, sonuç geliyorsa izleme
    if (alerts.length) alerts.push(`sıklık da yüksek: ${dec(freq)} (${FREQ_LABEL})`);
    else if (comparable && costPct != null && costPct >= COST_UP / 2) alerts.push(`sıklık ${dec(freq)} (${FREQ_LABEL}) ve mesaj başı maliyet %${Math.round(costPct)} arttı`);
    else notes.push(`sıklık ${dec(freq)} (${FREQ_LABEL}), maliyet şimdilik normal`);
  }

  sets.push({
    name: multiCampaign ? `${g.campaign} › ${g.name}` : g.name,
    status: alerts.length ? 'uyari' : notes.length ? 'izlemede' : 'normal',
    yesterday: d,
    ownAverage: { days: p.length, costPerConversation: baseCpc, conversations: pConv },
    frequency: freq,
    alerts,
    notes,
  });
}
const rank = { uyari: 0, izlemede: 1, normal: 2 };
sets.sort((a, b) => rank[a.status] - rank[b.status] || b.yesterday.spend - a.yesterday.spend);
const alertCount = sets.filter(s => s.status === 'uyari').length;

const lines = [
  header,
  alertCount
    ? `⚠️ <b>${alertCount} reklam setinde dikkat gereken durum var</b>`
    : '✅ Reklam setlerinde dikkat gereken bir durum yok',
  '',
  `💬 Mesaj başlatan: <b>${int(y.conversations)}</b> (ilk kez yazan: ${int(y.newContacts)})${trend(y.conversations, base?.conversations)}`,
  `💰 Mesaj başı maliyet: <b>${money(y.costPerConversation)}</b>${trend(y.costPerConversation, base?.costPerConversation, true)}`,
  `👥 Tekil erişim: <b>${int(y.reach)}</b>${trend(y.reach, base?.reach)}`,
  `👁 Gösterim: ${int(y.impressions)} · Sıklık: ${dec(y.frequency)}`,
  `💸 Harcama: <b>${money(y.spend)}</b> · CPM: ${money(y.cpm)}`,
];
if (sets.length) {
  lines.push('', '<b>Reklam setleri</b>');
  for (const s of sets.slice(0, MAX_SET_LINES)) {
    const d = s.yesterday;
    const figures = d.conversations > 0
      ? `${int(d.conversations)} mesaj · ${money(d.costPerConversation)}/mesaj · ${money(d.spend)}`
      : `0 mesaj · ${money(d.spend)}`;
    const icon = s.status === 'uyari' ? '⚠️' : s.status === 'izlemede' ? '👀' : '•';
    const name = s.status === 'uyari' ? `<b>${esc(s.name)}</b>` : esc(s.name);
    lines.push(`${icon} ${name}: ${figures}`);
    for (const t of [...s.alerts, ...s.notes]) lines.push(`   ↳ ${esc(t)}`);
  }
  if (sets.length > MAX_SET_LINES) lines.push(`… ve ${sets.length - MAX_SET_LINES} set daha`);
}
if (base) lines.push('', `<i>Oklar: önceki ${base.days} günün ortalamasına göre. Her set kendi önceki günleriyle karşılaştırılır.</i>`);

return [{ json: {
  hasData: true,
  text: lines.join('\n'),
  stats: {
    tarih: yStr,
    para_birimi: currency,
    dun: y,
    onceki_gunler_ortalama: base,
    reklam_setleri: sets,
    esikler: { siklik: FREQ_LIMIT, siklik_donemi: FREQ_LABEL, maliyet_artis_yuzde: COST_UP, min_harcama: MIN_SPEND },
  },
} }];

// Gemini yorumunu rapora ekler; Gemini hata verirse rapor yorumsuz gider
const report = $('Raporu Hazırla').first().json.text;
const resp = $input.first().json || {};
const parts = (resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts) || [];
const comment = parts.filter(p => p.text && !p.thought).map(p => p.text).join('\n').trim();
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const text = comment ? `${report}\n\n🤖 <b>Yapay zekâ yorumu</b>\n${esc(comment)}` : report;
return [{ json: { text } }];

// Rapor gönderildi: bugün tekrar gönderme
const s = $getWorkflowStaticData('global');
s.lastSentDate = $now.setZone('Europe/Istanbul').toFormat('yyyy-MM-dd');
return $input.all();

// Workflow hata verirse Telegram'a haber verir. Akış her 5 dakikada bir tekrar
// denediği için uyarı günde en fazla bir kez gider.
const s = $getWorkflowStaticData('global');
const today = $now.setZone('Europe/Istanbul').toFormat('yyyy-MM-dd');
if (s.lastErrorAlertDate === today) return [];
s.lastErrorAlertDate = today;

const d = $input.first().json || {};
const ex = d.execution || {};
const trig = (d.trigger && d.trigger.error) || {};
const node = ex.lastNodeExecuted || (trig.node && trig.node.name) || 'bilinmiyor';
const raw = (ex.error && (ex.error.description || ex.error.message)) || trig.message || 'Hata mesajı yok';
const message = String(raw).replace(/access_token=[^&\s"']+/gi, 'access_token=***').slice(0, 500);
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const lines = [
  '⚠️ <b>Meta reklam raporu alınamadı</b>',
  `Adım: ${esc(node)}`,
  `Hata: ${esc(message)}`,
];
if (/access token|session has expired|OAuthException|"code":\s*190/i.test(raw)) {
  lines.push('', "Meta token'ının süresi dolmuş görünüyor. n8n'de \"Meta Ads Token\" kimlik bilgisini yenilemek gerekiyor.");
}
lines.push('', 'Akış her 5 dakikada bir tekrar deniyor; düzelirse rapor kendiliğinden gelir. Bugün başka hata uyarısı gönderilmeyecek.');
if (ex.url) lines.push(`<a href="${esc(ex.url)}">Çalıştırmayı aç</a>`);

return [{ json: { text: lines.join('\n') } }];
